export default [
{
id: 'da01', group: 'duan', level: 1, minutes: 7,
title: 'Đánh giá chủ đầu tư trước khi giới thiệu dự án',
intro: 'Khách mua căn hộ trên giấy thực chất là đặt niềm tin vào chủ đầu tư. Sale nắm được chủ đầu tư làm ăn thế nào thì trả lời được câu hỏi khó nhất của khách: "Bên này có đáng tin không em?".',
sections: [
{ h: 'Nhìn vào dự án đã bàn giao, không nhìn vào lời giới thiệu', p: 'Thước đo tốt nhất là những dự án chủ đầu tư đã làm xong: bàn giao có đúng hẹn không, cư dân đã nhận sổ hồng chưa, vận hành sau bàn giao ra sao. Ví dụ trước khi giới thiệu một dự án mới ở Hoàng Mai, sale nên ghé một toà chủ đầu tư đã bàn giao vài năm, hỏi bảo vệ và cư dân về thang máy, bãi xe, phí dịch vụ. Một buổi đi thực tế như vậy giá trị hơn cả bộ tài liệu bán hàng.' },
{ h: 'Năng lực tài chính và tình trạng dự án', p: 'Chủ đầu tư niêm yết thì có báo cáo tài chính công bố, sale đọc được nợ vay, dòng tiền và các khoản trái phiếu đến hạn. Chủ đầu tư không niêm yết thì xem quy mô vốn, đối tác xây dựng, ngân hàng tài trợ hoặc bảo lãnh cho dự án. Dấu hiệu cần dè dặt: dự án cũ chậm tiến độ nhiều lần, cư dân cũ đang khiếu nại chưa được giải quyết, liên tục đổi tên dự án hoặc đổi pháp nhân bán hàng.' },
{ h: 'Tra thông tin công khai', p: 'Luật Kinh doanh bất động sản 2023 buộc doanh nghiệp công khai thông tin về bất động sản, dự án đưa vào kinh doanh trên hệ thống thông tin về nhà ở và thị trường bất động sản và trên trang web của doanh nghiệp, trước khi bán. Sale nên mở trang của chủ đầu tư và cổng thông tin của Sở Xây dựng để đối chiếu tên pháp nhân, tên dự án và các văn bản đã công bố. Tên trên hợp đồng mua bán phải trùng với pháp nhân chủ đầu tư được giao dự án, không phải một công ty "đối tác phân phối" nào đó; với nhà hình thành trong tương lai, chủ đầu tư không được uỷ quyền cho bên khác ký hợp đồng đặt cọc, mua bán.' },
{ h: 'Nói với khách thế nào cho đúng mực', p: 'Trình bày bằng dữ kiện: "Bên này đã bàn giao ba dự án ở Hà Nội, dự án gần nhất cư dân đã nhận sổ, em có ảnh thực tế anh/chị xem". Nếu có điểm yếu như một dự án cũ chậm sổ thì nói thẳng kèm lý do đã biết, khách sẽ tin sale hơn. Tuyệt đối không bình luận xấu về chủ đầu tư khác để nâng dự án của mình.' },
],
exercise: 'Chọn dự án bạn đang bán. Lập một trang ghi: tên pháp nhân chủ đầu tư, 3 dự án đã bàn giao (năm bàn giao, đã có sổ chưa), 1 điểm mạnh và 1 điểm cần lưu ý. Gọi thử cho một đồng nghiệp đóng vai khách và trình bày trong 2 phút.',
takeaways: [
'Dự án đã bàn giao và tình trạng sổ hồng là bằng chứng mạnh nhất về chủ đầu tư.',
'Tên pháp nhân trên hợp đồng phải đúng chủ đầu tư được giao dự án.',
'Thông tin dự án phải được công khai trước khi bán; sale đối chiếu trước khi tư vấn.',
'Nói điểm yếu kèm dữ kiện, không chê chủ đầu tư khác.',
],
refs: [
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 6 – công khai thông tin bất động sản, dự án đưa vào kinh doanh' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 23 khoản 4 điểm d – không uỷ quyền ký hợp đồng đặt cọc, mua bán nhà ở hình thành trong tương lai' },
],
quiz: [
{ q: 'Khách hỏi: "Chủ đầu tư này có uy tín không em?". Câu trả lời nào tốt nhất?', options: ['Dạ uy tín lắm anh/chị, ai cũng biết', 'Dạ bên này đã bàn giao ba dự án ở Hà Nội, dự án gần nhất cư dân đã có sổ, em gửi anh/chị ảnh và địa chỉ để mình qua xem thực tế', 'Dạ uy tín hơn hẳn chủ đầu tư bên cạnh', 'Dạ anh/chị cứ yên tâm, em đảm bảo'], answer: 1, why: 'Dữ kiện kiểm chứng được (dự án đã bàn giao, đã có sổ, có địa chỉ xem thực tế) thuyết phục hơn lời khen chung chung; chê đối thủ hay "đảm bảo" miệng đều không nên.' },
{ q: 'Dấu hiệu nào nên khiến sale dè dặt khi đánh giá một chủ đầu tư?', options: ['Chủ đầu tư có trang web riêng', 'Chủ đầu tư thuê đơn vị quản lý vận hành chuyên nghiệp', 'Dự án cũ chậm tiến độ nhiều lần và cư dân còn khiếu nại chưa giải quyết', 'Chủ đầu tư có ngân hàng tài trợ vốn'], answer: 2, why: 'Lịch sử chậm tiến độ và khiếu nại tồn đọng là rủi ro thực tế lặp lại được; ba điều còn lại là dấu hiệu bình thường hoặc tích cực.' },
{ q: 'Theo Luật Kinh doanh bất động sản 2023, thông tin dự án đưa vào kinh doanh phải được công khai khi nào?', options: ['Trước khi đưa dự án, bất động sản vào kinh doanh', 'Sau khi bàn giao nhà cho khách', 'Chỉ khi khách yêu cầu', 'Sau khi bán được một nửa số căn'], answer: 0, why: 'Điều 6 yêu cầu công khai đầy đủ, trung thực trước khi đưa vào kinh doanh, trên hệ thống thông tin về nhà ở và thị trường bất động sản và trang web doanh nghiệp.', ref: 'Điều 6 Luật 29/2023/QH15' },
{ q: 'Trên hợp đồng mua bán căn hộ, bên bán nên là ai?', options: ['Bất kỳ sàn phân phối nào có văn phòng lớn', 'Pháp nhân chủ đầu tư được giao dự án', 'Cá nhân giám đốc dự án', 'Công ty quản lý vận hành toà nhà'], answer: 1, why: 'Hợp đồng phải ký với chủ đầu tư dự án; sàn chỉ môi giới. Với nhà ở hình thành trong tương lai, luật không cho chủ đầu tư uỷ quyền cho tổ chức, cá nhân khác ký hợp đồng đặt cọc, mua bán.', ref: 'Điều 23 khoản 4 điểm d Luật 29/2023/QH15' },
{ q: 'Cách kiểm chất lượng vận hành sau bàn giao của chủ đầu tư hiệu quả nhất là gì?', options: ['Đọc brochure dự án mới', 'Hỏi trưởng phòng kinh doanh của chủ đầu tư', 'Xem video quảng cáo trên mạng', 'Đến một toà đã bàn giao, hỏi cư dân và bảo vệ về thang máy, bãi xe, phí dịch vụ'], answer: 3, why: 'Trải nghiệm thật của cư dân phản ánh đúng cách chủ đầu tư vận hành; tài liệu bán hàng thường chỉ nói điểm mạnh.' },
{ q: 'Dự án cũ của chủ đầu tư từng chậm sổ hồng một năm. Khách hỏi, sale nên làm gì?', options: ['Nói chưa nghe thấy chuyện đó', 'Nói thẳng là có, kèm lý do đã biết và tình trạng hiện nay, rồi nêu điểm khác ở dự án đang bán', 'Đổi sang chuyện chiết khấu cho khách quên đi', 'Bảo khách dự án nào cũng chậm sổ'], answer: 1, why: 'Thừa nhận dữ kiện và giải thích rõ giữ được niềm tin; né tránh hay quy chụp "dự án nào cũng thế" làm khách nghi ngờ hơn.' },
],
},
{
id: 'da02', group: 'duan', level: 1, minutes: 6,
title: 'Vị trí và kết nối: đo thời gian đi lại thực tế',
intro: '"Cách trung tâm 15 phút" là câu quen thuộc trên tờ rơi, nhưng khách sống ở đó mỗi ngày sẽ đi giờ cao điểm. Sale đo được thời gian thật thì tư vấn trúng nhu cầu và không bị khách bắt bẻ sau này.',
sections: [
{ h: 'Khoảng cách khác thời gian', p: 'Mười hai cây số đi giờ thấp điểm có thể mất 20 phút, nhưng giờ cao điểm sáng qua cầu Vĩnh Tuy hay đường Nguyễn Trãi có thể gấp đôi. Khách không mua khoảng cách, khách mua thời gian đưa con đi học và đến chỗ làm. Vì vậy hỏi khách trước: đi làm ở đâu, con học trường nào, giờ đi giờ về, rồi mới đo.' },
{ h: 'Cách đo cho chuẩn', p: 'Dùng ứng dụng bản đồ với chế độ chọn giờ khởi hành, đặt 7 giờ 15 sáng ngày thường và 17 giờ 30 chiều, ghi lại cả hai chiều. Tốt hơn nữa là tự đi thử một lần bằng xe máy và ô tô vào giờ cao điểm, quay màn hình đồng hồ khi xuất phát và khi đến. Ghi kết quả thành khoảng, ví dụ "35 đến 45 phút giờ cao điểm", không ghi một con số đẹp nhất.' },
{ h: 'Hạ tầng đã có, đang làm và mới trên giấy', p: 'Tách rõ ba loại khi nói về kết nối: tuyến đã chạy (như các tuyến metro đang khai thác), tuyến đang thi công có tiến độ công bố, và tuyến mới nằm trong quy hoạch. Chỉ tính thời gian đi lại hiện tại theo hạ tầng đã có. Hạ tầng tương lai là điểm cộng, nhưng phải nói kèm "theo kế hoạch" và không lấy làm cam kết.' },
{ h: 'Biến số liệu thành câu tư vấn', p: 'Ví dụ: "Anh làm ở Cầu Giấy, em đo sáng thứ Ba từ dự án đi mất khoảng 40 phút ô tô, đi metro rồi đi bộ khoảng 35 phút. Chị đưa bé đến trường cách 1,2 km, đi xe máy chừng 5 phút." Khách thấy sale tính cho đúng đời sống của mình thì tin tưởng hơn bất kỳ bản đồ quảng cáo nào.' },
],
exercise: 'Chọn 3 điểm đến phổ biến của khách dự án bạn bán (một khu văn phòng, một trường học, một bệnh viện). Đo thời gian lúc 7h15 và 17h30 ngày thường bằng bản đồ có chọn giờ khởi hành, ghi thành bảng khoảng thời gian để gửi khách.',
takeaways: [
'Hỏi nơi làm, nơi học của khách trước rồi mới đo.',
'Đo giờ cao điểm cả hai chiều, ghi thành khoảng thời gian.',
'Tách hạ tầng đã có, đang làm và mới trên quy hoạch.',
'Hạ tầng tương lai nói kèm "theo kế hoạch", không coi là cam kết.',
],
quiz: [
{ q: 'Tờ rơi ghi "cách Hoàn Kiếm 15 phút". Sale nên làm gì trước khi nói với khách?', options: ['Nhắc lại đúng con số trên tờ rơi', 'Đo lại bằng bản đồ có chọn giờ khởi hành vào giờ cao điểm, hoặc đi thử, rồi nói khoảng thời gian thực tế', 'Nói "khoảng 10 phút" cho hấp dẫn hơn', 'Bỏ qua vì khách tự biết'], answer: 1, why: 'Con số quảng cáo thường đo giờ thấp điểm; khách sống thật ở giờ cao điểm. Đo lại giúp tư vấn đúng và tránh khách phật ý sau khi dọn về.' },
{ q: 'Kết quả đo thời gian nên ghi thế nào cho khách?', options: ['Một con số nhanh nhất từng đo được', 'Con số trung bình cả ngày', 'Khoảng thời gian giờ cao điểm, ví dụ 35 đến 45 phút, cả chiều đi và về', 'Chỉ ghi khoảng cách theo km'], answer: 2, why: 'Khoảng thời gian giờ cao điểm cả hai chiều phản ánh trải nghiệm thật; con số nhanh nhất hay số km dễ gây hiểu sai.' },
{ q: 'Khi tính thời gian đi lại hiện tại cho khách, nên dùng hạ tầng nào?', options: ['Hạ tầng đã đưa vào khai thác', 'Tuyến metro mới có trong quy hoạch', 'Cây cầu đang lấy ý kiến dự thảo', 'Tất cả các tuyến có trong bản đồ quy hoạch chung'], answer: 0, why: 'Chỉ hạ tầng đã chạy mới tạo ra thời gian đi lại hôm nay; tuyến đang làm hay trên quy hoạch là điểm cộng tương lai, phải nói kèm "theo kế hoạch".' },
{ q: 'Việc đầu tiên khi tư vấn về vị trí cho một gia đình có con nhỏ là gì?', options: ['Kể các tiện ích nội khu', 'Đưa bản đồ liên kết vùng', 'Báo giá căn đẹp nhất', 'Hỏi bố mẹ làm ở đâu, con học trường nào, giờ đi giờ về'], answer: 3, why: 'Biết điểm đến hằng ngày của khách thì mới đo đúng tuyến đường quan trọng với họ; tư vấn vị trí chung chung không chạm nhu cầu.' },
{ q: 'Khách hỏi: "Tuyến đường vành đai sắp làm xong đúng không em?". Câu nào phù hợp?', options: ['Dạ chắc chắn năm sau xong ạ', 'Dạ theo kế hoạch công bố thì dự kiến hoàn thành vào thời điểm đó; em gửi anh/chị nguồn tin, còn hiện tại mình đi đường này mất khoảng 40 phút giờ cao điểm', 'Dạ cái đó không quan trọng đâu ạ', 'Dạ xong rồi anh/chị ạ'], answer: 1, why: 'Nói đúng trạng thái "theo kế hoạch", có nguồn, kèm thời gian đi lại hiện tại; không hứa mốc hoàn thành thay cơ quan nhà nước.' },
],
},
{
id: 'da03', group: 'duan', level: 1, minutes: 8,
title: 'Đọc mặt bằng căn hộ: tim tường, thông thuỷ, công năng, hướng, view',
intro: 'Hai căn cùng ghi "70 m²" có thể chênh nhau vài mét vuông sử dụng thật. Sale đọc được mặt bằng căn sẽ giải thích giá đúng cách và chọn căn hợp gia đình khách.',
sections: [
{ h: 'Tim tường và thông thuỷ', p: 'Diện tích tim tường đo từ giữa tường bao, nên tính cả một phần tường và cột. Diện tích thông thuỷ là phần lọt lòng dùng được. Theo Luật Nhà ở 2023, diện tích sử dụng căn hộ tính theo kích thước thông thuỷ, gồm cả ban công, lô gia và phần tường ngăn các phòng bên trong căn, không tính tường bao, tường phân chia giữa các căn, diện tích có cột và hộp kỹ thuật bên trong căn. Khi so giá, luôn hỏi chủ đầu tư đang báo trên diện tích nào. Luật Nhà ở (sửa đổi) đã thông qua ngày 21/11/2026, ngày hiệu lực theo văn bản khi được công bố; trước khi luật mới có hiệu lực, áp dụng quy định hiện hành.' },
{ h: 'Quy về giá trên mét vuông thông thuỷ', p: 'Ví dụ một căn giá 4,2 tỷ đồng, tim tường 70 m², thông thuỷ 64 m². Tính theo tim tường là 60 triệu/m², nhưng theo thông thuỷ là khoảng 65,6 triệu/m². Phần chênh 6 m² tương đương gần 8,6% diện tích. So hai dự án mà một bên báo tim tường, một bên báo thông thuỷ thì phải quy về cùng một loại mới công bằng.' },
{ h: 'Công năng: đi vào từng phòng trên bản vẽ', p: 'Xem căn có vuông vức không, phòng ngủ có kê được giường và tủ không, có góc nhọn hay hành lang dài lãng phí diện tích không. Kiểm vị trí bếp và vệ sinh có cửa sổ thông gió không, lô gia phơi đồ ở đâu, cục nóng điều hoà đặt chỗ nào. Gia đình có người già nên ưu tiên phòng ngủ có vệ sinh riêng gần cửa ra vào.' },
{ h: 'Hướng và view', p: 'Ở Hà Nội nhiều khách thích ban công hướng Nam, Đông Nam vì đón gió mát và tránh nắng chiều; căn hướng Tây thường nóng buổi chiều, cần rèm và kính phù hợp. Phân biệt hướng ban công và hướng cửa chính vì chủ đầu tư có thể ghi theo một trong hai. View phải xem cả hiện tại và tương lai: lô đất trống trước mặt có quy hoạch toà cao tầng không, nếu có thì view đẹp hôm nay có thể bị che.' },
],
exercise: 'Lấy mặt bằng 3 căn khác nhau trong dự án bạn bán. Với mỗi căn ghi: diện tích tim tường, thông thuỷ, giá trên m² thông thuỷ (tính bằng máy tính), hướng ban công, một điểm cộng và một điểm trừ về công năng.',
takeaways: [
'Diện tích sử dụng căn hộ theo luật tính theo thông thuỷ.',
'So giá giữa các dự án phải quy về cùng loại diện tích.',
'Đọc công năng từng phòng: kê đồ, thông gió, cục nóng điều hoà.',
'Ghi rõ hướng ban công hay hướng cửa; xem cả view tương lai.',
],
refs: [
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 143 khoản 1 – xác định diện tích sử dụng căn hộ theo kích thước thông thuỷ' },
],
quiz: [
{ q: 'Theo Luật Nhà ở 2023, diện tích sử dụng căn hộ được tính theo cách nào?', options: ['Theo tim tường bao', 'Theo kích thước thông thuỷ', 'Theo diện tích sàn xây dựng cả tầng chia đều', 'Theo thoả thuận, không có quy định'], answer: 1, why: 'Luật quy định diện tích sử dụng căn hộ tính theo kích thước thông thuỷ; tim tường chỉ là cách chủ đầu tư hay dùng khi giới thiệu.', ref: 'Điều 143 Luật Nhà ở 27/2023/QH15' },
{ q: 'Phần nào KHÔNG được tính vào diện tích thông thuỷ của căn hộ?', options: ['Ban công', 'Lô gia', 'Tường ngăn giữa các phòng bên trong căn', 'Tường bao căn hộ và hộp kỹ thuật bên trong căn'], answer: 3, why: 'Thông thuỷ gồm ban công, lô gia và tường ngăn phòng bên trong; không tính tường bao, tường chung giữa các căn, cột và hộp kỹ thuật.', ref: 'Điều 143 Luật Nhà ở 27/2023/QH15' },
{ q: 'Ví dụ căn 4,2 tỷ, tim tường 70 m², thông thuỷ 64 m². Giá trên m² thông thuỷ xấp xỉ bao nhiêu?', options: ['60 triệu/m²', '62 triệu/m²', '65,6 triệu/m²', '70 triệu/m²'], answer: 2, why: '4.200 triệu chia 64 m² ≈ 65,6 triệu/m²; con số 60 triệu là chia theo tim tường.' },
{ q: 'Dự án A báo giá theo tim tường, dự án B báo theo thông thuỷ. Sale nên làm gì khi khách muốn so?', options: ['Quy cả hai về giá trên m² thông thuỷ rồi mới so', 'Lấy thẳng hai con số ra so', 'Nói dự án báo thông thuỷ luôn đắt hơn', 'Bỏ qua vì chênh lệch không đáng kể'], answer: 0, why: 'Chênh giữa tim tường và thông thuỷ có thể vài phần trăm diện tích, đủ làm sai kết luận rẻ hay đắt nếu không quy đổi.' },
{ q: 'Chủ đầu tư ghi "căn hướng Đông Nam". Sale cần hỏi lại điều gì?', options: ['Căn có bao nhiêu ổ cắm', 'Đó là hướng ban công hay hướng cửa chính', 'Tầng mấy có thang máy dừng', 'Màu sơn tường'], answer: 1, why: 'Hướng ban công và hướng cửa chính thường ngược nhau; khách quan tâm phong thuỷ hoặc nắng gió cần biết chính xác đang ghi theo hướng nào.' },
{ q: 'Căn có view hồ đẹp nhưng lô đất trống trước mặt nằm trong quy hoạch toà cao tầng. Sale nên nói gì?', options: ['Không nhắc tới để khách chốt nhanh', 'Hứa view sẽ giữ mãi', 'Nói view hiện tại đẹp, đồng thời cho khách biết lô trước mặt có quy hoạch xây cao tầng để khách cân nhắc', 'Khuyên khách đừng mua căn đó'], answer: 2, why: 'Nói đủ hiện trạng và quy hoạch giúp khách tự quyết; giấu thông tin dễ dẫn tới khiếu nại về sau.' },
],
},
{
id: 'da04', group: 'duan', level: 2, minutes: 7,
title: 'Mặt bằng tổng thể, mật độ xây dựng và tiện ích nội khu',
intro: 'Phối cảnh dự án nào cũng đẹp. Sale cần đọc mặt bằng tổng thể để trả lời những câu khách quan tâm khi đã ở: có đông quá không, chờ thang máy lâu không, con chơi ở đâu, xe để đâu.',
sections: [
{ h: 'Đọc mặt bằng tổng thể', p: 'Tìm trên bản vẽ: số toà, số tầng, số căn mỗi sàn, vị trí lối vào, đường nội bộ, khu cây xanh, trường mầm non, bể bơi và bãi đỗ xe. Xem căn của khách nằm gần hay xa tiện ích, có quay ra đường lớn ồn ào hay nhìn vào sân trong. Hỏi chủ đầu tư phần nào đã xây, phần nào làm sau, vì tiện ích ghi "giai đoạn 2" có thể chưa có khi khách nhận nhà.' },
{ h: 'Mật độ xây dựng và mật độ dân cư', p: 'Mật độ xây dựng là tỷ lệ phần đất có công trình trên tổng diện tích lô đất; mật độ thấp thì còn nhiều đất cho cây xanh, sân chơi. Nhưng cảm giác đông đúc còn đến từ số người ở. Ví dụ dự án 2 toà, mỗi toà 30 tầng, 20 căn mỗi sàn: tổng 1.200 căn, nếu bình quân 3,2 người mỗi căn thì khoảng 3.840 cư dân dùng chung một khu tiện ích. Số liệu mật độ chính xác của dự án lấy theo quy hoạch chi tiết đã được duyệt, không ước lượng thay.' },
{ h: 'Thang máy, bãi xe, tiện ích theo đầu người', p: 'Ví dụ mỗi toà 30 tầng, 20 căn mỗi sàn, có 6 thang máy chở người: bình quân 100 căn một thang. Con số này giúp khách hình dung giờ cao điểm sáng. Hỏi thêm số chỗ đỗ ô tô so với số căn, phí gửi xe, có thang hàng riêng không. Tiện ích nội khu nên quy về trải nghiệm: bể bơi bao nhiêu người dùng chung, sân chơi trẻ em cách sảnh mấy bước chân.' },
{ h: 'Nói với khách bằng con số so sánh được', p: 'Thay vì "tiện ích đẳng cấp", sale nói: "Toà này 20 căn một sàn, 6 thang máy, chỗ đỗ ô tô có hạn nên anh/chị cần đăng ký sớm; sân chơi ngay dưới sảnh toà của mình". Khách gia đình trẻ sẽ quan tâm trường mầm non nội khu đã có chủ đầu tư vận hành chưa hay mới là quỹ đất.' },
],
exercise: 'Từ mặt bằng tổng thể dự án bạn bán, tính: tổng số căn, số căn bình quân mỗi thang máy, số chỗ đỗ ô tô so với số căn (nếu có số liệu). Ghi 3 tiện ích đã hoàn thành và tiện ích nào thuộc giai đoạn sau.',
takeaways: [
'Tiện ích ghi "giai đoạn sau" có thể chưa có khi nhận nhà, phải hỏi rõ.',
'Mật độ xây dựng là tỷ lệ đất có công trình; cảm giác đông đúc còn do số cư dân.',
'Số căn mỗi thang máy và chỗ đỗ xe là chỉ số khách ở thật rất quan tâm.',
'Số liệu mật độ chính thức lấy theo quy hoạch chi tiết đã duyệt.',
],
quiz: [
{ q: 'Mật độ xây dựng của một lô đất được hiểu là gì?', options: ['Số người ở trên mỗi hecta', 'Tỷ lệ diện tích đất có công trình xây dựng trên tổng diện tích lô đất', 'Số tầng trung bình của các toà', 'Tổng diện tích sàn chia cho số căn'], answer: 1, why: 'Mật độ xây dựng đo phần đất bị công trình chiếm; số người trên hecta là mật độ dân cư, còn tổng sàn trên đất liên quan hệ số sử dụng đất.' },
{ q: 'Ví dụ dự án 2 toà, mỗi toà 30 tầng, 20 căn mỗi sàn, bình quân 3,2 người mỗi căn. Số cư dân ước tính là bao nhiêu?', options: ['1.200 người', '1.920 người', '3.840 người', '6.000 người'], answer: 2, why: '2 × 30 × 20 = 1.200 căn; 1.200 × 3,2 = 3.840 người dùng chung tiện ích.' },
{ q: 'Mỗi toà 30 tầng, 20 căn mỗi sàn, có 6 thang máy chở người. Bình quân bao nhiêu căn một thang?', options: ['100 căn', '60 căn', '120 căn', '200 căn'], answer: 0, why: '30 × 20 = 600 căn mỗi toà; 600 chia 6 = 100 căn một thang máy.' },
{ q: 'Tờ giới thiệu ghi "trường liên cấp nội khu". Sale nên kiểm điều gì trước khi nói với khách có con nhỏ?', options: ['Màu sắc của trường trong phối cảnh', 'Trường đã xây và vận hành chưa, hay mới là quỹ đất dự kiến, thuộc giai đoạn nào', 'Trường có bể bơi không', 'Tên kiến trúc sư thiết kế trường'], answer: 1, why: 'Tiện ích trên phối cảnh có thể chỉ là quỹ đất; gia đình có con cần biết khi nhận nhà đã có trường chưa.' },
{ q: 'Số liệu mật độ xây dựng chính xác của dự án nên lấy ở đâu?', options: ['Ước lượng từ ảnh phối cảnh', 'Hỏi cư dân xung quanh', 'Lấy theo dự án tương tự gần đó', 'Theo quy hoạch chi tiết hoặc tổng mặt bằng đã được cơ quan có thẩm quyền phê duyệt'], answer: 3, why: 'Chỉ tiêu quy hoạch chính thức nằm trong quy hoạch chi tiết, tổng mặt bằng được duyệt; ước lượng dễ sai và không có giá trị khi tư vấn.' },
{ q: 'Câu tư vấn nào về tiện ích là tốt nhất?', options: ['Tiện ích đẳng cấp 5 sao, anh/chị yên tâm', 'Tiện ích nhiều nhất khu vực', 'Toà mình 20 căn một sàn, 6 thang máy; sân chơi ngay dưới sảnh, bể bơi đã vận hành ở toà bên cạnh', 'Có đủ mọi thứ anh/chị cần'], answer: 2, why: 'Con số cụ thể và trạng thái đã vận hành giúp khách hình dung đời sống; tính từ chung chung không kiểm chứng được.' },
],
},
{
id: 'da05', group: 'duan', level: 2, minutes: 9,
title: 'Hồ sơ pháp lý dự án: đủ điều kiện bán nhà hình thành trong tương lai',
intro: 'Câu khách hỏi nhiều nhất với căn hộ trên giấy là "pháp lý thế nào em?". Sale cần biết bộ hồ sơ đi theo thứ tự nào, và giấy nào chứng minh dự án đã được phép bán.',
sections: [
{ h: 'Chuỗi hồ sơ từ chủ trương đến mở bán', p: 'Một dự án nhà ở thương mại thường đi qua: văn bản chấp thuận chủ trương đầu tư và nhà đầu tư (theo Luật Đầu tư 2025, số 143/2025/QH15, hiệu lực từ 01/3/2026), quy hoạch chi tiết hoặc tổng mặt bằng được duyệt, quyết định giao đất hoặc cho thuê đất, giấy phép xây dựng (theo Luật Xây dựng 2025, số 135/2025/QH15, hiệu lực từ 01/7/2026, trừ trường hợp được miễn), khởi công, nghiệm thu móng, rồi mới tới văn bản xác nhận đủ điều kiện bán. Sale không cần thuộc từng điều, nhưng phải biết thứ tự để nhận ra dự án đang đứng ở bước nào.' },
{ h: 'Điều kiện đưa nhà hình thành trong tương lai vào kinh doanh', p: 'Theo Điều 24 Luật Kinh doanh bất động sản 2023, nhà ở hình thành trong tương lai phải đã khởi công theo pháp luật xây dựng, có giấy tờ về quyền sử dụng đất (như quyết định giao đất, cho thuê đất), có giấy phép xây dựng hoặc hồ sơ thiết kế khi được miễn phép, có nghiệm thu hạ tầng kỹ thuật theo tiến độ dự án, và với nhà chung cư thì phải có biên bản nghiệm thu hoàn thành phần móng. Chủ đầu tư còn phải công khai thông tin dự án trước khi bán. Luật Kinh doanh bất động sản (sửa đổi) đã thông qua ngày 21/11/2026, hiệu lực từ 01/7/2027; trước ngày đó áp dụng quy định hiện hành.' },
{ h: 'Văn bản của Sở Xây dựng và bảo lãnh ngân hàng', p: 'Trước khi bán, chủ đầu tư phải gửi văn bản thông báo tới cơ quan quản lý nhà nước về kinh doanh bất động sản cấp tỉnh (ở Hà Nội là Sở Xây dựng); trong 15 ngày cơ quan này kiểm tra và trả lời bằng văn bản nhà ở có đủ điều kiện bán hay không (khoản 4 Điều 24, trình tự tại Điều 8 Nghị định 96/2024/NĐ-CP). Đây là tờ giấy sale nên xin bản chụp để gửi khách. Ngoài ra, Điều 26 của luật quy định bảo lãnh của ngân hàng cho nghĩa vụ tài chính của chủ đầu tư khi không bàn giao nhà đúng cam kết; khi ký hợp đồng, người mua được chọn có hay không có bảo lãnh (khoản 3 Điều 26), nên sale cần hỏi rõ dự án đã có văn bản cam kết phát hành bảo lãnh của ngân hàng chưa.' },
{ h: 'Danh sách hỏi chủ đầu tư', p: 'Trước mỗi đợt mở bán, sale chuẩn bị các câu: văn bản đủ điều kiện bán số mấy, ngày nào, áp dụng cho toà nào; ngân hàng nào bảo lãnh; dự án có đang thế chấp không và đã giải chấp phần căn bán chưa; hợp đồng ký với pháp nhân nào. Văn bản đủ điều kiện bán thường ghi cụ thể toà, số căn, nên căn của khách phải nằm trong danh sách đó; văn bản này cũng nêu rõ việc nhà ở đã được giải chấp (Điều 183 khoản 2 Luật Nhà ở 2023).' },
],
exercise: 'Lập checklist pháp lý cho dự án bạn đang bán theo đúng thứ tự trong bài, đánh dấu giấy nào bạn đã có bản chụp, giấy nào còn thiếu. Gửi trưởng nhóm danh sách giấy còn thiếu để xin chủ đầu tư.',
takeaways: [
'Nhà chung cư hình thành trong tương lai phải có nghiệm thu móng trước khi bán.',
'Văn bản của Sở Xây dựng xác nhận đủ điều kiện bán là giấy quan trọng nhất để gửi khách.',
'Kiểm căn của khách có nằm trong danh sách căn đủ điều kiện bán không.',
'Hỏi rõ bảo lãnh ngân hàng và tình trạng thế chấp, giải chấp.',
],
refs: [
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 24 – điều kiện nhà ở hình thành trong tương lai đưa vào kinh doanh' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 26 – bảo lãnh trong bán, cho thuê mua nhà ở hình thành trong tương lai' },
{ t: 'Nghị định 96/2024/NĐ-CP hướng dẫn Luật Kinh doanh bất động sản, Điều 8 – thông báo nhà ở đủ điều kiện bán' },
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 183 khoản 2 – giải chấp trước khi ký hợp đồng mua bán' },
{ t: 'Luật Đầu tư 2025 (số 143/2025/QH15)', whole: true },
{ t: 'Luật Xây dựng 2025 (số 135/2025/QH15)', whole: true },
],
quiz: [
{ q: 'Với nhà chung cư hình thành trong tương lai, hạng mục xây dựng nào phải được nghiệm thu trước khi đưa vào kinh doanh?', options: ['Hoàn thiện mặt ngoài', 'Cất nóc toà nhà', 'Lắp đặt thang máy', 'Phần móng'], answer: 3, why: 'Điều 24 Luật Kinh doanh bất động sản 2023 yêu cầu với nhà chung cư, toà nhà hỗn hợp có nhà ở phải có biên bản nghiệm thu hoàn thành phần móng.', ref: 'Điều 24 Luật 29/2023/QH15' },
{ q: 'Khách hỏi: "Dự án được phép bán chưa em?". Giấy tờ nào sale nên gửi để trả lời trực tiếp nhất?', options: ['Ảnh phối cảnh dự án', 'Văn bản của Sở Xây dựng trả lời nhà ở đủ điều kiện bán, có ghi toà và căn áp dụng', 'Giấy chứng nhận đăng ký doanh nghiệp của sàn', 'Thư mời dự lễ mở bán'], answer: 1, why: 'Văn bản của cơ quan quản lý kinh doanh bất động sản cấp tỉnh là xác nhận chính thức nhà ở đủ điều kiện bán; các giấy còn lại không chứng minh điều đó.', ref: 'Điều 8 Nghị định 96/2024/NĐ-CP' },
{ q: 'Điều nào sau đây KHÔNG thuộc điều kiện đưa nhà ở hình thành trong tương lai vào kinh doanh theo Điều 24?', options: ['Đã khởi công xây dựng', 'Có giấy tờ về quyền sử dụng đất như quyết định giao đất', 'Đã bán được ít nhất 30% số căn', 'Có giấy phép xây dựng hoặc hồ sơ thiết kế khi được miễn phép'], answer: 2, why: 'Luật không đặt điều kiện về số căn đã bán; các điều kiện là khởi công, giấy tờ đất, giấy phép xây dựng, nghiệm thu hạ tầng và móng.', ref: 'Điều 24 Luật 29/2023/QH15' },
{ q: 'Về bảo lãnh ngân hàng khi mua nhà hình thành trong tương lai, nhận định nào đúng?', options: ['Bảo lãnh bảo đảm cho chất lượng hoàn thiện căn hộ', 'Bảo lãnh bảo đảm nghĩa vụ tài chính của chủ đầu tư khi không bàn giao nhà đúng cam kết', 'Luật cấm người mua từ chối bảo lãnh', 'Bảo lãnh chỉ áp dụng với nhà đã có sẵn'], answer: 1, why: 'Điều 26 quy định bảo lãnh cho nghĩa vụ tài chính của chủ đầu tư khi không bàn giao nhà theo cam kết; người mua được chọn có yêu cầu bảo lãnh hay không.', ref: 'Điều 26 Luật 29/2023/QH15' },
{ q: 'Văn bản đủ điều kiện bán ghi áp dụng cho toà A. Khách muốn mua căn ở toà B cùng dự án. Sale nên làm gì?', options: ['Kiểm toà B đã có văn bản đủ điều kiện bán chưa, chưa có thì nói rõ với khách và không nhận tiền', 'Bán luôn vì cùng một dự án', 'Ký "phiếu giữ chỗ" để thu tiền trước', 'Đổi số căn trên giấy sang toà A'], answer: 0, why: 'Điều kiện bán xét theo từng toà, căn trong văn bản; thu tiền khi toà chưa đủ điều kiện đặt khách vào rủi ro và vi phạm quy định về đặt cọc.' },
{ q: 'Thứ tự hồ sơ nào hợp lý nhất cho một dự án nhà ở thương mại?', options: ['Mở bán → giao đất → chủ trương đầu tư', 'Giấy phép xây dựng → chủ trương đầu tư → giao đất', 'Nghiệm thu móng → chủ trương đầu tư → mở bán', 'Chủ trương đầu tư → giao đất → giấy phép xây dựng → nghiệm thu móng → văn bản đủ điều kiện bán'], answer: 3, why: 'Dự án phải có chủ trương và nhà đầu tư, rồi có đất, có phép xây dựng, thi công tới móng, cuối cùng mới được xác nhận đủ điều kiện bán.' },
],
},
{
id: 'da06', group: 'duan', level: 2, minutes: 9,
title: 'Chính sách bán hàng: quy đổi chiết khấu, hỗ trợ lãi và tiến độ về giá thực',
intro: 'Mỗi đợt mở bán có cả chục ưu đãi: chiết khấu, hỗ trợ lãi suất, thanh toán nhanh, tặng gói nội thất. Khách rối. Sale quy đổi được về "giá thực phải trả" sẽ giúp khách chọn đúng phương án và tự tin chốt.',
sections: [
{ h: 'Giới hạn luật về đặt cọc và tiến độ thanh toán', p: 'Với nhà hình thành trong tương lai, chủ đầu tư chỉ được thu tiền đặt cọc khi nhà đã đủ điều kiện đưa vào kinh doanh, và mức cọc không quá 5% giá bán (Điều 23 khoản 5 Luật Kinh doanh bất động sản 2023). Theo Điều 25, lần thanh toán đầu không quá 30% giá trị hợp đồng kể cả tiền cọc; tổng tiền thu trước khi bàn giao không quá 70% (không quá 50% nếu bên bán là tổ chức có vốn đầu tư nước ngoài theo luật này); chưa cấp Giấy chứng nhận cho người mua thì không thu quá 95%. Luật Kinh doanh bất động sản (sửa đổi) đã thông qua ngày 21/11/2026, hiệu lực từ 01/7/2027; trước ngày đó áp dụng quy định hiện hành.' },
{ h: 'Ba phương án và cách quy đổi', p: 'Ví dụ căn giá niêm yết 5 tỷ đồng (đã gồm VAT, chưa gồm kinh phí bảo trì 2%). Phương án A: chiết khấu 3%, đóng theo tiến độ, giá còn 4,85 tỷ. Phương án B: thêm chiết khấu thanh toán nhanh 5% trên giá sau chiết khấu, giá còn khoảng 4,6075 tỷ, nhưng khách phải đóng sớm khoảng 3,23 tỷ (70%). Phương án C: vay 60% giá sau chiết khấu (2,91 tỷ), chủ đầu tư hỗ trợ lãi suất 18 tháng.' },
{ h: 'Tính lợi ích thật của từng gói', p: 'Gói B không "rẻ" 242,5 triệu tròn: tiền đóng sớm có chi phí cơ hội. Ví dụ khách phải đóng sớm hơn tiến độ thường khoảng 2 tỷ trong một năm, chi phí cơ hội 6%/năm thì mất khoảng 120 triệu, giá quy đổi khoảng 4,73 tỷ. Gói C: nếu lãi vay 9%/năm trên 2,91 tỷ trong 18 tháng thì khoản hỗ trợ tối đa khoảng 393 triệu, giá quy đổi khoảng 4,46 tỷ; đây là mức trần vì ngân hàng giải ngân theo tiến độ, dư nợ thực tế thấp hơn. Sau thời gian hỗ trợ, khách tự trả lãi thả nổi.' },
{ h: 'Đọc kỹ điều kiện ưu đãi', p: 'Hỏi: hỗ trợ lãi tính trên dư nợ tối đa bao nhiêu phần trăm, kết thúc khi nào, trả nợ trước hạn có bị thu lại ưu đãi không; chiết khấu tính trên giá trước hay sau VAT; quà tặng nội thất có quy ra tiền được không. Gói thanh toán nhanh với nhà hình thành trong tương lai phải tuân giới hạn 70% trước bàn giao, nên cần xem cách chủ đầu tư thiết kế gói trên văn bản. Mọi ưu đãi phải ghi trong hợp đồng hoặc phụ lục, không chỉ trên tờ chính sách.' },
],
exercise: 'Lấy chính sách bán hàng hiện hành của dự án bạn bán, chọn một căn cụ thể, tính giá quy đổi cho ít nhất 2 phương án thanh toán (ghi rõ giả định lãi suất, chi phí cơ hội). Trình bày trong một bảng 3 dòng để gửi khách.',
takeaways: [
'Cọc nhà hình thành trong tương lai: chỉ thu khi đủ điều kiện kinh doanh, không quá 5% giá bán.',
'Đợt đầu ≤ 30%, trước bàn giao ≤ 70% (50% với bên bán có vốn nước ngoài theo luật), chưa có sổ ≤ 95%.',
'Quy đổi ưu đãi về giá thực, tính cả chi phí cơ hội và thời hạn hỗ trợ lãi.',
'Ưu đãi phải ghi vào hợp đồng hoặc phụ lục.',
],
refs: [
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 23 khoản 5 – đặt cọc nhà ở hình thành trong tương lai không quá 5% giá bán' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 25 – thanh toán trong mua bán, thuê mua nhà ở hình thành trong tương lai' },
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 152 – kinh phí bảo trì 2% giá trị căn hộ' },
],
quiz: [
{ q: 'Theo Luật Kinh doanh bất động sản 2023, mức đặt cọc tối đa khi mua nhà ở hình thành trong tương lai là bao nhiêu?', options: ['10% giá bán', '5% giá bán', '30% giá trị hợp đồng', 'Không giới hạn, do hai bên thoả thuận'], answer: 1, why: 'Khoản 5 Điều 23 giới hạn tiền đặt cọc không quá 5% giá bán, và chỉ được thu khi nhà đã đủ điều kiện đưa vào kinh doanh.', ref: 'Điều 23 khoản 5 Luật 29/2023/QH15' },
{ q: 'Căn giá 4 tỷ đồng, chủ đầu tư trong nước. Trước khi bàn giao nhà, tổng tiền chủ đầu tư được thu tối đa là bao nhiêu?', options: ['1,2 tỷ', '3,8 tỷ', '2 tỷ', '2,8 tỷ'], answer: 3, why: 'Tổng thu trước bàn giao không quá 70% giá trị hợp đồng: 4 tỷ × 70% = 2,8 tỷ. 1,2 tỷ là trần đợt đầu (30%), 3,8 tỷ là trần 95% khi chưa có sổ.', ref: 'Điều 25 Luật 29/2023/QH15' },
{ q: 'Ví dụ căn 5 tỷ, chiết khấu 3% rồi thêm 5% thanh toán nhanh trên giá sau chiết khấu. Giá sau ưu đãi là bao nhiêu?', options: ['4,6 tỷ', '4,6075 tỷ', '4,85 tỷ', '4,65 tỷ'], answer: 1, why: '5 tỷ × 0,97 = 4,85 tỷ; 4,85 × 0,95 = 4,6075 tỷ. Cộng dồn 8% (4,6 tỷ) là sai vì chiết khấu thứ hai tính trên giá đã giảm.' },
{ q: 'Vì sao giá quy đổi của gói thanh toán nhanh phải cộng thêm chi phí cơ hội?', options: ['Vì luật bắt buộc', 'Vì khách phải nộp thêm phí', 'Vì tiền đóng sớm lẽ ra có thể gửi tiết kiệm hoặc giảm nợ vay, đó là phần lợi khách bỏ qua', 'Vì ngân hàng thu phí trả sớm'], answer: 2, why: 'Đóng sớm làm khách mất lợi ích từ khoản tiền đó trong thời gian chờ; cộng chi phí cơ hội mới so được với gói đóng theo tiến độ.' },
{ q: 'Gói hỗ trợ lãi suất 18 tháng: ước tính 393 triệu tính trên toàn bộ khoản vay ngay từ đầu. Nhận định nào đúng?', options: ['Đó là mức trần, thực tế thường thấp hơn vì ngân hàng giải ngân theo tiến độ', 'Đó là số chính xác khách được nhận', 'Khách luôn được nhận nhiều hơn', 'Hỗ trợ lãi không có giá trị gì'], answer: 0, why: 'Dư nợ tăng dần theo các đợt giải ngân nên tiền lãi được hỗ trợ thực tế nhỏ hơn mức tính trên toàn khoản vay.' },
{ q: 'Khi chưa cấp Giấy chứng nhận cho người mua, chủ đầu tư được thu tối đa bao nhiêu phần trăm giá trị hợp đồng?', options: ['100%', '90%', '95%', '70%'], answer: 2, why: 'Điều 25 quy định khi bên mua chưa được cấp Giấy chứng nhận thì bên bán không được thu quá 95%; 5% còn lại thanh toán khi cơ quan có thẩm quyền cấp giấy.', ref: 'Điều 25 Luật 29/2023/QH15' },
{ q: 'Khách hỏi: "Giá 5 tỷ đã gồm hết chưa em?". Sale cần nói thêm khoản nào thường tính riêng?', options: ['Kinh phí bảo trì phần sở hữu chung 2% giá trị căn hộ (nếu giá chưa gồm)', 'Lệ phí trước bạ do chủ đầu tư nộp thay', 'Phí môi giới do khách trả cho sàn', 'Thuế thu nhập cá nhân của chủ đầu tư'], answer: 0, why: 'Luật Nhà ở 2023 quy định kinh phí bảo trì 2% giá trị căn hộ; bảng giá thường ghi rõ đã hay chưa gồm khoản này, sale phải nói để khách tính đủ.', ref: 'Điều 152 Luật Nhà ở 27/2023/QH15' },
],
},
{
id: 'da07', group: 'duan', level: 2, minutes: 7,
title: 'Thị trường khu vực: giá giao dịch thực tế khác giá rao',
intro: 'Giá trên các trang rao vặt là giá người bán mong muốn, không phải giá người mua đã trả. Sale nắm giá giao dịch thật thì định giá đúng cho khách bán và tư vấn đúng cho khách mua.',
sections: [
{ h: 'Vì sao giá rao thường cao hơn giá chốt', p: 'Người bán thường rao cao để có khoảng mặc cả, nhiều tin rao cũ không gỡ, có tin rao giá "mồi" thấp bất thường để kéo khách gọi. Một căn có thể được nhiều môi giới đăng với nhiều mức giá. Vì vậy trung bình giá rao trên mạng thường không phản ánh mức khách thật sự trả.' },
{ h: 'Nguồn giá giao dịch đáng tin hơn', p: 'Sale nên gom giá từ: các căn chính mình hoặc đồng nghiệp đã chốt trong 3 đến 6 tháng gần nhất, giá ghi trên hợp đồng chuyển nhượng khách đồng ý chia sẻ, mức định giá của ngân hàng khi khách vay, và trao đổi với ban quản lý hay môi giới lâu năm trong toà. Mỗi giá ghi kèm ngày, tầng, diện tích, hướng và tình trạng nội thất.' },
{ h: 'Lọc và tính cho đúng', p: 'Ví dụ ở một dự án tại Nam Từ Liêm, sale gom 7 tin rao căn 2 phòng ngủ: 62, 65, 68, 70, 72, 75 và 90 triệu/m², trung vị là 70 triệu/m². Năm giao dịch thực trong quý: 58, 60, 61, 63, 64 triệu/m², trung vị 61 triệu/m², thấp hơn giá rao khoảng 12,9%. Dùng trung vị thay vì trung bình để tin rao 90 triệu bất thường không kéo lệch kết quả.' },
{ h: 'Dùng số liệu khi tư vấn', p: 'Với khách bán: "Tin rao quanh 70 triệu/m², nhưng các căn đã bán thật quý này quanh 61 triệu/m². Nếu anh/chị muốn bán trong hai tháng thì nên đặt giá gần mức giao dịch". Với khách mua: dùng giá giao dịch làm mốc trả giá. Luôn nói đây là số mẫu của sale tự gom, không phải số liệu thống kê chính thức.' },
],
exercise: 'Chọn một dự án bạn hay giao dịch. Gom ít nhất 5 tin rao và 3 giá giao dịch thật cùng loại căn trong 6 tháng gần nhất, tính trung vị mỗi nhóm và phần trăm chênh lệch.',
takeaways: [
'Giá rao là giá mong muốn; giá giao dịch là giá đã trả.',
'Mỗi giá ghi kèm ngày, tầng, diện tích, hướng, nội thất.',
'Dùng trung vị để giảm ảnh hưởng của tin rao bất thường.',
'Nói rõ đây là số liệu mẫu tự gom khi trình bày với khách.',
],
quiz: [
{ q: 'Vì sao trung bình giá rao trên mạng thường không phản ánh giá khách thật sự trả?', options: ['Vì trang rao vặt tính sai', 'Vì người bán rao cao để mặc cả, có tin cũ chưa gỡ và tin giá mồi', 'Vì giá rao luôn thấp hơn giá thật', 'Vì luật cấm đăng giá thật'], answer: 1, why: 'Giá rao chứa khoảng mặc cả, tin trùng, tin cũ và tin mồi; giá chốt mới là mức người mua chấp nhận.' },
{ q: 'Nguồn nào cho giá giao dịch đáng tin nhất?', options: ['Tin rao mới đăng hôm nay', 'Ảnh chụp bảng giá của chủ đầu tư từ đợt mở bán đầu tiên', 'Bình luận trên mạng xã hội', 'Các căn đã chốt gần đây có ghi ngày, tầng, diện tích, hướng, nội thất'], answer: 3, why: 'Giao dịch đã chốt gần đây có đủ thông tin là mốc so sánh sát nhất; bảng giá cũ và bình luận không phản ánh giá hiện tại.' },
{ q: 'Bảy tin rao: 62, 65, 68, 70, 72, 75, 90 triệu/m². Trung vị là bao nhiêu?', options: ['70 triệu/m²', '71,7 triệu/m²', '72 triệu/m²', '68 triệu/m²'], answer: 0, why: 'Xếp tăng dần, giá trị đứng giữa (thứ 4 trong 7) là 70. Trung bình khoảng 71,7 bị tin 90 kéo lên.' },
{ q: 'Trung vị giá rao 70 triệu/m², trung vị giá giao dịch 61 triệu/m². Giá giao dịch thấp hơn giá rao khoảng bao nhiêu phần trăm?', options: ['9%', '14,8%', '12,9%', '7%'], answer: 2, why: '(70 − 61) chia 70 ≈ 12,9%. Con số 14,8% là chia cho 61, sai mốc so sánh.' },
{ q: 'Khách muốn bán nhanh nhưng đòi đặt giá theo tin rao cao nhất trong toà. Sale nên nói gì?', options: ['Đồng ý ngay để giữ khách', 'Đưa số giá đã giao dịch thật gần đây và thời gian bán dự kiến ở từng mức giá để khách tự chọn', 'Nói khách đặt giá như vậy là vô lý', 'Đặt giá thấp hơn mà không báo khách'], answer: 1, why: 'Dữ kiện giao dịch thật giúp khách hiểu đánh đổi giữa giá và tốc độ bán; quyết định vẫn thuộc về khách.' },
{ q: 'Khi trình bày bảng giá tự gom cho khách, sale nên lưu ý điều gì?', options: ['Gọi đó là số liệu chính thức của nhà nước', 'Chỉ đưa những giá có lợi cho mình', 'Làm tròn cho đẹp', 'Nói rõ đây là số mẫu sale tự gom, kèm số giao dịch và thời gian'], answer: 3, why: 'Minh bạch nguồn và cỡ mẫu giúp khách đánh giá đúng độ tin cậy; gán mác chính thức hoặc chọn lọc số liệu làm mất uy tín.' },
],
},
{
id: 'da08', group: 'duan', level: 3, minutes: 8,
title: 'So sánh dự án công bằng bằng bảng so cùng tiêu chí',
intro: 'Khách thường đang cân nhắc hai, ba dự án cùng lúc. Bảng so công bằng giúp khách thấy sale đứng về phía mình chứ không chỉ bênh dự án đang bán.',
sections: [
{ h: 'Quy về cùng đơn vị trước khi so', p: 'Giá phải cùng loại diện tích (thông thuỷ), cùng tình trạng thuế phí (đã hay chưa gồm VAT, kinh phí bảo trì), đã quy đổi chính sách bán hàng về giá thực, và so cùng loại căn (2 phòng ngủ so với 2 phòng ngủ, tầng trung so với tầng trung). Thời điểm bàn giao cũng phải ghi, vì căn bàn giao ngay và căn ba năm nữa mới nhận khác nhau về dòng tiền.' },
{ h: 'Chọn tiêu chí và trọng số theo khách', p: 'Tiêu chí thường dùng: pháp lý và tiến độ, giá thực, vị trí và thời gian đi lại, tiện ích, uy tín chủ đầu tư. Hỏi khách điều gì quan trọng nhất rồi gán trọng số, ví dụ pháp lý 30%, giá thực 25%, vị trí 20%, tiện ích 15%, chủ đầu tư 10%. Gia đình có con nhỏ có thể tăng trọng số tiện ích và trường học; nhà đầu tư cho thuê tăng trọng số lợi suất và thanh khoản.' },
{ h: 'Chấm điểm minh bạch', p: 'Ví dụ dự án X được 8, 6, 9, 7, 8 điểm theo năm tiêu chí trên, tổng có trọng số 7,55. Dự án Y được 6, 9, 7, 8, 6, tổng 7,25. X nhỉnh hơn nhờ pháp lý và vị trí, Y hơn rõ về giá. Mỗi điểm số phải ghi lý do ngắn bên cạnh (vì sao pháp lý được 8, vì sao vị trí được 9) để khách đọc lại cũng hiểu.' },
{ h: 'Trình bày không chê bai', p: 'Bảng so nêu sự khác biệt bằng dữ kiện, không dùng từ như "kém", "tệ". Nếu dự án sale đang bán thua ở một tiêu chí, cứ để đúng điểm và nói rõ. Kết luận nên là: "Với ưu tiên của anh/chị là pháp lý và đường đi làm thì X phù hợp hơn; nếu ưu tiên tổng tiền thì Y đáng cân nhắc". Khách tự chọn và tin sale vì sự công bằng.' },
],
exercise: 'Lập bảng so 2 dự án mà khách gần nhất của bạn đang cân nhắc: quy giá về thông thuỷ và giá thực, hỏi lại khách để gán trọng số 5 tiêu chí, chấm điểm có ghi lý do, rồi tính tổng có trọng số.',
takeaways: [
'Quy về cùng đơn vị: thông thuỷ, cùng thuế phí, đã quy đổi ưu đãi, cùng loại căn.',
'Trọng số do ưu tiên của khách quyết định, không do sale tự đặt.',
'Mỗi điểm số ghi lý do ngắn, kiểm chứng được.',
'Để đúng điểm cả khi dự án mình bán thua một tiêu chí.',
],
quiz: [
{ q: 'Điều nào cần làm TRƯỚC khi so giá hai dự án?', options: ['Chọn dự án mình bán làm mốc 10 điểm', 'Quy cả hai về giá trên m² thông thuỷ, cùng tình trạng thuế phí và đã quy đổi ưu đãi', 'Lấy giá niêm yết cao nhất của mỗi bên', 'So giá căn góc của bên này với căn giữa của bên kia'], answer: 1, why: 'Không cùng đơn vị và cùng điều kiện thì so giá sẽ sai; mốc cố định cho dự án mình bán là thiên vị.' },
{ q: 'Trọng số: pháp lý 30%, giá 25%, vị trí 20%, tiện ích 15%, chủ đầu tư 10%. Dự án X được 8, 6, 9, 7, 8. Tổng có trọng số là bao nhiêu?', options: ['7,6', '7,25', '7,55', '8,0'], answer: 2, why: '8×0,30 + 6×0,25 + 9×0,20 + 7×0,15 + 8×0,10 = 2,4 + 1,5 + 1,8 + 1,05 + 0,8 = 7,55. Trung bình không trọng số là 7,6.' },
{ q: 'Ai nên quyết định trọng số giữa các tiêu chí?', options: ['Ưu tiên thật của khách, sale hỏi rồi gán', 'Chủ đầu tư dự án sale đang bán', 'Sale tự đặt cố định cho mọi khách', 'Trưởng phòng kinh doanh'], answer: 0, why: 'Mỗi khách có ưu tiên khác nhau; trọng số phản ánh nhu cầu của khách thì kết quả mới có ích cho họ.' },
{ q: 'Dự án sale đang bán thua rõ ở tiêu chí giá. Cách làm đúng là gì?', options: ['Bỏ tiêu chí giá khỏi bảng', 'Hạ điểm giá của dự án kia xuống', 'Giảm trọng số giá mà không hỏi khách', 'Giữ đúng điểm, nói rõ và nêu dự án mình mạnh ở tiêu chí nào'], answer: 3, why: 'Bảng so chỉ có giá trị khi trung thực; chỉnh điểm hay bỏ tiêu chí sẽ làm khách mất niềm tin khi tự kiểm lại.' },
{ q: 'Căn A bàn giao ngay, căn B ba năm nữa mới nhận nhà. Khi so, sale nên lưu ý gì?', options: ['Không cần quan tâm vì giá mới là chính', 'Ghi rõ thời điểm bàn giao vì ảnh hưởng dòng tiền, tiền thuê nhà trong lúc chờ và rủi ro tiến độ', 'Luôn chấm căn bàn giao muộn thấp điểm hơn', 'Luôn chấm căn bàn giao muộn cao điểm hơn vì giá rẻ'], answer: 1, why: 'Thời điểm nhận nhà thay đổi chi phí thực của khách (thuê nhà, lãi vay) và rủi ro; phải đưa vào bảng chứ không chấm theo cảm tính.' },
{ q: 'Câu kết luận nào phù hợp nhất cho bảng so?', options: ['Dự án Y kém lắm anh/chị đừng mua', 'Dự án X là tốt nhất thị trường', 'Với ưu tiên pháp lý và đường đi làm của anh/chị thì X phù hợp hơn; nếu ưu tiên tổng tiền thì Y đáng cân nhắc', 'Anh/chị cứ chọn bừa, dự án nào cũng như nhau'], answer: 2, why: 'Kết luận gắn với ưu tiên của khách, nêu đánh đổi rõ ràng, không chê dự án khác và để khách tự quyết.' },
],
},
{
id: 'da09', group: 'duan', level: 3, minutes: 8,
title: 'Phân tích lợi suất cho thuê của căn hộ',
intro: 'Khách đầu tư hỏi "cho thuê được bao nhiêu phần trăm một năm?". Con số tờ rơi thường là lợi suất gộp. Sale tính được lợi suất ròng thì tư vấn thật, tránh khách kỳ vọng sai.',
sections: [
{ h: 'Lợi suất gộp và lợi suất ròng', p: 'Lợi suất gộp bằng tiền thuê cả năm chia giá mua. Lợi suất ròng trừ đi các khoản thực tế: tháng trống không có khách thuê, phí quản lý dịch vụ, sửa chữa, thay đồ, phí môi giới tìm khách, thuế cho thuê, và tính trên tổng vốn bỏ ra gồm cả nội thất. Hai con số này có thể chênh nhau đáng kể.' },
{ h: 'Ví dụ tính từng bước', p: 'Ví dụ căn 70 m² giá 3,5 tỷ, làm nội thất 200 triệu, cho thuê 15 triệu/tháng. Lợi suất gộp trên giá mua: 180 triệu chia 3.500 triệu ≈ 5,14%. Giả sử trống 1 tháng mỗi năm, thu thực 165 triệu; phí quản lý 12.000 đồng/m²/tháng là khoảng 10,08 triệu/năm; sửa chữa và chi phí khác 6 triệu. Thu nhập ròng trước thuế ≈ 148,92 triệu, chia tổng vốn 3.700 triệu ≈ 4,02%/năm.' },
{ h: 'Thuế và chi phí vay', p: 'Thu nhập cho thuê nhà của cá nhân có thể phải nộp thuế theo quy định hiện hành; ngưỡng doanh thu và tỷ lệ tính thuế đã thay đổi theo các luật thuế mới, sale nên xem bài nhóm Thuế phí hoặc hỏi kế toán trước khi đưa số cho khách. Nếu khách vay mua, tiền lãi vay phải đặt cạnh tiền thuê: lãi vay cao hơn lợi suất ròng nghĩa là khách đang bù tiền mỗi tháng.' },
{ h: 'Kiểm giá thuê thật trước khi tính', p: 'Giá thuê lấy từ hợp đồng thuê đang có ở cùng toà hoặc toà lân cận, cùng loại căn và mức nội thất, không lấy từ tin rao cao nhất. Lượng căn bàn giao cùng lúc lớn thì giai đoạn đầu cạnh tranh thuê mạnh, giá thuê và tỷ lệ lấp đầy có thể thấp hơn kỳ vọng. Khi nói với khách, trình bày cả kịch bản thận trọng và không hứa mức lợi suất.' },
],
exercise: 'Chọn một căn đang có khách đầu tư hỏi. Tìm ít nhất 3 giá thuê thực tế cùng loại căn quanh đó, tính lợi suất gộp và lợi suất ròng (ghi rõ giả định tháng trống, phí quản lý, nội thất). Lập thêm kịch bản thận trọng với giá thuê thấp hơn 10%.',
takeaways: [
'Lợi suất gộp = tiền thuê năm / giá mua; lợi suất ròng trừ đủ chi phí và tính trên tổng vốn.',
'Tính cả tháng trống, phí quản lý, sửa chữa, nội thất, thuế.',
'Giá thuê lấy từ hợp đồng thật cùng loại căn, không từ tin rao cao nhất.',
'Đưa kịch bản thận trọng, không hứa mức lợi suất.',
],
quiz: [
{ q: 'Căn giá 3,5 tỷ, cho thuê 15 triệu/tháng. Lợi suất gộp trên giá mua xấp xỉ bao nhiêu?', options: ['4,02%', '5,14%', '4,86%', '6,0%'], answer: 1, why: '15 × 12 = 180 triệu; 180 chia 3.500 ≈ 5,14%. 4,86% là chia cho tổng vốn 3,7 tỷ; 4,02% là lợi suất ròng.' },
{ q: 'Khoản nào KHÔNG nên trừ khi tính lợi suất ròng cho thuê?', options: ['Tháng trống không có khách', 'Phí quản lý dịch vụ chủ nhà phải trả', 'Chi phí sửa chữa, thay đồ', 'Tiền khách thuê tự trả điện nước hằng tháng'], answer: 3, why: 'Điện nước do khách thuê tự trả không phải chi phí của chủ nhà; ba khoản còn lại làm giảm thu nhập ròng.' },
{ q: 'Ví dụ thu nhập ròng 148,92 triệu/năm, tổng vốn gồm nội thất 3,7 tỷ. Lợi suất ròng xấp xỉ bao nhiêu?', options: ['4,02%', '4,25%', '3,58%', '5,14%'], answer: 0, why: '148,92 chia 3.700 ≈ 4,02%. Nếu chia cho giá mua 3,5 tỷ (4,25%) là bỏ quên vốn nội thất.' },
{ q: 'Khách vay 70% để mua căn cho thuê, lãi vay đang cao hơn lợi suất ròng. Điều đó nghĩa là gì?', options: ['Khách lãi nhiều hơn', 'Không ảnh hưởng gì', 'Tiền thuê không đủ trả lãi, khách phải bù thêm tiền mỗi tháng', 'Ngân hàng sẽ giảm lãi tự động'], answer: 2, why: 'Khi chi phí vay vượt thu nhập ròng từ thuê, dòng tiền âm; khách cần biết để chuẩn bị nguồn bù.' },
{ q: 'Giá thuê đưa vào tính lợi suất nên lấy từ đâu?', options: ['Hợp đồng thuê thực tế cùng loại căn, cùng mức nội thất ở toà hoặc toà lân cận', 'Tin rao cao nhất trên mạng', 'Con số chủ đầu tư ghi trên tờ rơi', 'Giá thuê của căn penthouse cùng dự án'], answer: 0, why: 'Hợp đồng thật cùng loại căn phản ánh giá thị trường; tin rao cao nhất và tờ rơi dễ làm lợi suất bị thổi phồng.' },
{ q: 'Khách hỏi: "Mua căn này cho thuê được 7% một năm đúng không em?". Câu trả lời nào phù hợp?', options: ['Dạ đúng, em đảm bảo 7%', 'Dạ chắc chắn trên 7%', 'Dạ cho thuê không có lời đâu ạ', 'Dạ em tính theo giá thuê thực tế quanh đây thì lợi suất gộp khoảng 5%, trừ chi phí còn khoảng 4%; em gửi anh/chị bảng tính và kịch bản thận trọng'], answer: 3, why: 'Đưa số tính từ dữ liệu thật, phân biệt gộp và ròng, kèm kịch bản thận trọng; không hứa mức lợi suất.' },
],
},
{
id: 'da10', group: 'duan', level: 3, minutes: 9,
title: 'Nhận diện rủi ro dự án và cách nói với khách',
intro: 'Dự án nào cũng có rủi ro. Sale giỏi không giấu rủi ro mà gọi đúng tên, nói cách kiểm và cách khách tự bảo vệ mình. Khách nhớ người nói thật lâu hơn người chỉ khen.',
sections: [
{ h: 'Rủi ro pháp lý và thu tiền sớm', p: 'Dấu hiệu nặng nhất: dự án chưa có văn bản đủ điều kiện bán nhưng đã thu tiền dưới tên "giữ chỗ", "đăng ký nguyện vọng". Luật Kinh doanh bất động sản 2023 chỉ cho thu tiền đặt cọc khi nhà ở hình thành trong tương lai đã đủ điều kiện đưa vào kinh doanh, mức không quá 5% giá bán. Khoản tiền thu trước thời điểm đó khách rất khó đòi lại khi có vấn đề. Sale gặp tình huống này nên báo khách rõ và báo trưởng nhóm. Luật Kinh doanh bất động sản (sửa đổi) đã thông qua ngày 21/11/2026, hiệu lực từ 01/7/2027; trước ngày đó áp dụng quy định hiện hành.' },
{ h: 'Rủi ro tiến độ, tài chính và thế chấp', p: 'Chủ đầu tư vay nợ nhiều, trái phiếu sắp đến hạn hoặc nhà thầu xây dựng thay đổi liên tục là dấu hiệu tiến độ có thể chậm. Dự án đang thế chấp tại ngân hàng thì phải giải chấp phần căn bán trước khi ký hợp đồng với khách. Luật cũng giới hạn chủ đầu tư không thu quá 95% giá trị hợp đồng khi người mua chưa được cấp Giấy chứng nhận; 5% cuối là đòn bẩy để khách được làm sổ.' },
{ h: 'Rủi ro quy hoạch, thanh khoản và vận hành', p: 'Quy hoạch xung quanh có thể thay đổi view, mật độ dân cư và hạ tầng. Dự án có nhiều căn đầu tư cùng bàn giao thì giai đoạn đầu khó cho thuê và khó bán lại nhanh. Phí dịch vụ, chỗ đỗ xe và chất lượng quản lý vận hành ảnh hưởng trực tiếp đời sống. Mỗi rủi ro nên đi kèm một cách kiểm cụ thể: tra quy hoạch, hỏi số căn bàn giao cùng đợt, đọc dự thảo hợp đồng quản lý vận hành.' },
{ h: 'Khung nói chuyện: gọi tên, kiểm, giảm thiểu', p: 'Ví dụ: "Dự án này bàn giao sau khoảng hai năm, rủi ro chính là tiến độ. Em đã kiểm: dự án có văn bản đủ điều kiện bán của Sở Xây dựng, có ngân hàng bảo lãnh, nghiệm thu móng rồi. Anh/chị có quyền yêu cầu bảo lãnh, và theo luật 5% cuối chỉ đóng khi nhận sổ". Cách nói này không hứa hẹn, không chê ai, nhưng cho khách thấy rủi ro đã được kiểm soát tới đâu.' },
],
exercise: 'Với dự án bạn đang bán, viết 3 rủi ro chính. Mỗi rủi ro ghi: dấu hiệu, cách kiểm, cách khách giảm thiểu. Tập nói theo khung "gọi tên, kiểm, giảm thiểu" trong 90 giây với đồng nghiệp.',
takeaways: [
'Thu tiền "giữ chỗ" khi chưa đủ điều kiện bán là dấu hiệu rủi ro nặng.',
'Kiểm giải chấp, bảo lãnh và văn bản đủ điều kiện bán trước khi khách ký.',
'Chưa có sổ thì chủ đầu tư không được thu quá 95% giá trị hợp đồng.',
'Nói rủi ro theo khung: gọi tên, cách kiểm, cách giảm thiểu.',
],
refs: [
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 23 khoản 5 – điều kiện và mức thu tiền đặt cọc' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 25 – giới hạn thanh toán, 95% khi chưa cấp Giấy chứng nhận' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 26 – bảo lãnh nhà ở hình thành trong tương lai' },
],
quiz: [
{ q: 'Dự án chưa có văn bản đủ điều kiện bán nhưng đang thu "phí giữ chỗ" 100 triệu. Sale nên làm gì?', options: ['Thu ngay kẻo hết căn đẹp', 'Nói với khách đây là khoản thu trước khi dự án đủ điều kiện, rủi ro cao, và báo trưởng nhóm', 'Ghi vào hợp đồng là "đặt cọc" cho hợp lệ', 'Bảo khách chuyển khoản vào tài khoản cá nhân của sale'], answer: 1, why: 'Luật chỉ cho thu đặt cọc khi đã đủ điều kiện đưa vào kinh doanh; khoản thu trước đó khó đòi lại. Đổi tên thành "đặt cọc" không làm nó hợp lệ.', ref: 'Điều 23 khoản 5 Luật 29/2023/QH15' },
{ q: 'Căn giá 4 tỷ, khách chưa được cấp Giấy chứng nhận. Chủ đầu tư được thu tối đa bao nhiêu?', options: ['4 tỷ', '2,8 tỷ', '3,8 tỷ', '3,6 tỷ'], answer: 2, why: 'Chưa cấp Giấy chứng nhận thì không thu quá 95%: 4 tỷ × 95% = 3,8 tỷ; 200 triệu còn lại thanh toán khi có giấy.', ref: 'Điều 25 Luật 29/2023/QH15' },
{ q: 'Dự án đang thế chấp tại ngân hàng. Điều gì cần kiểm trước khi khách ký hợp đồng mua căn?', options: ['Căn của khách đã được giải chấp chưa', 'Ngân hàng đó có nhiều chi nhánh không', 'Dự án có quảng cáo trên truyền hình không', 'Chủ đầu tư có trụ sở ở Hà Nội không'], answer: 0, why: 'Tài sản đang thế chấp phải được giải chấp phần bán trước khi ký với khách, nếu không quyền của khách có thể bị ảnh hưởng.' },
{ q: 'Khung nói rủi ro với khách gồm những bước nào?', options: ['Khen, hứa, chốt', 'Giấu rủi ro, chờ khách hỏi', 'So sánh với dự án đối thủ để thấy đối thủ tệ hơn', 'Gọi tên rủi ro, nói cách đã kiểm, nói cách khách giảm thiểu'], answer: 3, why: 'Gọi tên và cho thấy đã kiểm, kèm cách tự bảo vệ, giúp khách quyết định có cơ sở mà không cần hứa hẹn hay chê ai.' },
{ q: 'Khách lo dự án chậm bàn giao. Quyền nào theo luật sale nên nhắc khách?', options: ['Quyền đòi chủ đầu tư bồi thường gấp đôi giá', 'Quyền yêu cầu chủ đầu tư có bảo lãnh của ngân hàng cho nghĩa vụ tài chính khi không bàn giao đúng cam kết', 'Quyền tự vào công trường kiểm tra bất kỳ lúc nào', 'Quyền không phải thanh toán đợt nào cho tới khi bàn giao'], answer: 1, why: 'Điều 26 quy định bảo lãnh của ngân hàng trong bán nhà ở hình thành trong tương lai; người mua được chọn có yêu cầu bảo lãnh hay không. Các lựa chọn còn lại không có trong luật.', ref: 'Điều 26 Luật 29/2023/QH15' },
{ q: 'Dự án có hàng nghìn căn bàn giao cùng đợt, nhiều khách mua để cho thuê. Rủi ro nào sale nên nói với khách đầu tư?', options: ['Không có rủi ro gì', 'Giá thuê chắc chắn tăng vì đông người', 'Giai đoạn đầu cạnh tranh cho thuê và bán lại mạnh, giá thuê và thanh khoản có thể thấp hơn kỳ vọng', 'Chủ đầu tư sẽ thuê lại toàn bộ'], answer: 2, why: 'Nguồn cung lớn cùng lúc tạo áp lực cạnh tranh; nói trước giúp khách chuẩn bị kịch bản tài chính thận trọng.' },
{ q: 'Khách hỏi: "Dự án bên kia rẻ hơn, có vấn đề gì không em?". Câu trả lời nào đúng mực?', options: ['Bên đó pháp lý có vấn đề đấy anh/chị', 'Rẻ thì chắc chất lượng kém', 'Em không biết, anh/chị tự tìm hiểu', 'Em gửi anh/chị danh sách những giấy tờ nên kiểm ở bất kỳ dự án nào, mình đặt hai bên cạnh nhau để so cho công bằng'], answer: 3, why: 'Đưa công cụ kiểm tra chung giúp khách tự đánh giá; nói xấu dự án khác khi không có dữ kiện là sai đạo đức nghề và dễ gây rắc rối.' },
],
},
];
